const out = [];
async function dump(id, depth) {
  const n = await figma.getNodeByIdAsync(id);
  if (!n) return;
  const d = {id, name:n.name, type:n.type, w:Math.round(n.width), h:Math.round(n.height)};
  try { if (n.fills && n.fills !== figma.mixed) d.fills = JSON.stringify(n.fills).slice(0,200); } catch(e){}
  try { if (n.cornerRadius !== undefined && n.cornerRadius !== figma.mixed) d.r = n.cornerRadius; } catch(e){}
  try { if (n.strokes && n.strokes.length) d.strokes = JSON.stringify(n.strokes).slice(0,120); d.sw = n.strokeWeight; } catch(e){}
  if (n.type === "TEXT") { d.chars = n.characters; d.font = JSON.stringify(n.fontName); d.size = n.fontSize; try{d.color=JSON.stringify(n.fills[0].color)}catch(e){} }
  if (n.effects && n.effects.length) d.fx = JSON.stringify(n.effects).slice(0,150);
  out.push("  ".repeat(depth)+JSON.stringify(d));
  if ("children" in n && depth < 3) for (const c of n.children) await dump(c.id, depth+1);
}
await dump("1:473",0); // button
