const hex = h => { const v = parseInt(h.slice(1),16); return {r:((v>>16)&255)/255, g:((v>>8)&255)/255, b:(v&255)/255}; };
const solid = (h,o) => [{type:"SOLID", color:hex(h), opacity:o===undefined?1:o}];
const C = {red:"#EF2A39", ink:"#3C2F2F", bg:"#FAF7F4", surface:"#FFFFFF", border:"#EDE6E1", t2:"#8C7E7A", t3:"#B5A9A5", rating:"#F5A623", success:"#2FA35C", redSoft:"#FDE7E9", cream:"#F7EFE8"};
function T(chars, size, style, color, opts={}) {
  const t = figma.createText();
  t.fontName = {family:"Roboto", style};
  t.fontSize = size; t.characters = chars; t.fills = solid(color);
  if (opts.lh) t.lineHeight = {value:opts.lh, unit:"PIXELS"};
  if (opts.w) { t.textAutoResize="HEIGHT"; t.resize(opts.w, t.height); }
  if (opts.align) t.textAlignHorizontal = opts.align;
  if (opts.name) t.name = opts.name;
  return t;
}
function recolor(n, color) {
  if ("fills" in n && n.type !== "TEXT") { try { const f=n.fills; if (f!==figma.mixed && f.length) n.fills = solid(color); } catch(e){} }
  if ("strokes" in n) { try { if (n.strokes && n.strokes.length) n.strokes = solid(color); } catch(e){} }
  if ("children" in n) n.children.forEach(c=>recolor(c,color));
}
async function icon(compId, color, size) {
  const src = await figma.getNodeByIdAsync(compId);
  const inst = src.createInstance();
  if (size) inst.resize(size,size);
  if (color) recolor(inst, color);
  return inst;
}
async function imgRect(nodeId, w, h) {
  const src = await figma.getNodeByIdAsync(nodeId);
  const r = figma.createRectangle();
  r.fills = JSON.parse(JSON.stringify(src.fills));
  r.resize(w,h);
  return r;
}
