const section=async(title,items,yPos)=>{
  const sec=col("Section/"+title,10);
  const lbl=await txt(title,15,"Bold",INK);
  sec.appendChild(lbl);
  const scroller=row("Chips",12);
  for(const it of items){
    const chip=(await figma.getNodeByIdAsync("53:94")).createInstance();
    const food=chip.findOne(n=>n.name==="FoodImage");
    food.fills=[await imgFill(it.img)];
    const label=chip.findOne(n=>n.name==="Label");
    label.characters=it.name;
    if(it.added){
      chip.strokes=solid(RED); chip.strokeWeight=2;
      const badge=chip.findOne(n=>n.name==="Badge");
      badge.fills=solid(RED);
      // swap plus -> check
      const plus=badge.findOne(n=>n.type==="INSTANCE");
      const check=(await figma.getNodeByIdAsync("1:398")).createInstance();
      badge.appendChild(check);
      check.resize(plus.width,plus.height);
      check.x=plus.x; check.y=plus.y;
      plus.remove();
      const vecs=check.findAll(n=>n.type==="VECTOR");
      for(const v of vecs){ if(v.fills&&v.fills.length) v.fills=solid({r:1,g:1,b:1}); if(v.strokes&&v.strokes.length) v.strokes=solid({r:1,g:1,b:1}); }
    }
    scroller.appendChild(chip);
  }
  sec.appendChild(scroller);
  frame.appendChild(sec);
  sec.x=20; sec.y=yPos;
  return sec;
};

